128: function ensureAudio(){if(!audioCtx){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return null;audioCtx=new AudioContext();masterGain=audioCtx.createGain();masterGain.gain.value=muted?0:Number($('#volume-slider')?.value??70)/100;masterGain.connect(audioCtx.destination);ambienceFilter=audioCtx.createBiquadFilter();ambienceFilter.type='lowpass';ambienceFilter.frequency.value=150;ambienceGain=audioCtx.createGain();ambienceGain.gain.value=0;ambienceFilter.connect(ambienceGain);ambienceGain.connect(masterGain);for(const [freq,level,type] of [[46,.026,'sine'],[51,.014,'triangle']]){const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.value=level;osc.connect(gain);gain.connect(ambienceFilter);osc.start();}audioCtx.addEventListener('statechange',()=>{if(audioCtx?.state==='suspended'&&!document.hidden)audioCtx.resume().catch(()=>{});});}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return audioCtx;}
