function updateObjectives(){const idx=Math.min(game.objectiveDone.findIndex(done=>!done),6);$('#objective-text').textContent=objectives[game.lang][idx];$('#sector-name').textContent=tr(game.phase<2?'SEKTOR 01 · MEDIZIN':game.phase<3?'SEKTOR 02 · FORSCHUNG':'SEKTOR 03 · REAKTOR',game.phase<2?'SECTOR 01 · MEDICAL':game.phase<3?'SECTOR 02 · RESEARCH':'SECTOR 03 · REACTOR');$('#objective-progress').innerHTML=`KEYCARD ${String(game.keys).padStart(2,'0')} / 03 <span><i class="${game.keys>0?'filled':''}"></i><i class="${game.keys>1?'filled':''}"></i><i class="${game.keys>2?'filled':''}"></i></span>`;$('#log-list').innerHTML=objectives[game.lang].map((s,i)=>`<li class="${game.objectiveDone[i]?'complete':''}">${s}</li>`).join('');$('#squad-count').textContent=String(1+game.botCount).padStart(2,'0');const lift=interactables.find(i=>i.kind==='lift');if(lift)lift.label=game.called&&game.hold<=0?tr('Aufzug betreten','Board elevator'):tr('Oberflächenaufzug rufen','Call surface elevator');}
