derer.domElement.requestPointerLock?.();});document.addEventListener('pointerlockchange',()=>{pointer=document.pointerLockElement===renderer.domElement;});document.addEventListener('mousemove',e=>{if(pointer&&game.mode==='playing'&&!game.paused){const sens=Number($('#sensitivity-slider').value)/80*.0022;player.yaw-=e.movementX*sens;player.pitch=clamp(player.pitch-e.movementY*sens,-1.45,1.45);}});
