        const menu = document.querySelector('#main-menu')
        const title = menu?.querySelector('h1')
        const canvas = document.querySelector('#game')
        if (!menu || !title?.textContent?.trim() || !canvas || canvas.width === 0 || canvas.height === 0) return false
