const f=new THREE.Vector3(Math.sin(player.yaw),0,-Math.cos(player.yaw)),r=new THREE.Vector3(Math.cos(player.yaw),0,Math.sin(player.yaw));
const v=f.multiplyScalar(forward).add(r.multiplyScalar(side));
if(v.lengthSq()>0)v.normalize().multiplyScalar(speed*dt);
moveAxis('x',v.x);
moveAxis('z',v.z);
if(moving){bob+=dt*(sprint?11:7);
footstep-=dt;
if(footstep<=0){footstep=sprint?.28:.48;
playTone(sprint?78:95,.035,'triangle',sprint?.045:.018);
game.noise=sprint?1:.4;
}}else game.noise=Math.max(0,game.noise-dt);
camera.position.set(player.pos.x,1.66+Math.sin(bob)*.025,player.pos.z);
camera.rotation.set(player.pitch,player.yaw,0,'YXZ');
if(flashOn&&game.battery>0){game.battery=Math.max(0,game.battery-(.22+(sprint?.28:0))*dt);
if(game.battery===0){flashOn=false;
flashlight.intensity=0;
flashlight.userData.fill.intensity=0;
showToast(tr('Die Taschenlampe ist erloschen.','The flashlight has gone dark.'));
}}}updateMonster(dt);
updateBots(dt);
if(monster?.userData.active){const near=clamp(1-game.enemyDist/18,0,1);
game.fear=clamp(game.fear+(near*9-(1-near)*2)*dt,0,100);
}else game.fear=Math.max(0,game.fear-4*dt);
const current=nearInteraction();
$('#interaction').classList.toggle('show',!!current&&!game.paused&&!game.playerDown);
if(current)$('#interaction-text').textContent=current.label;
updateHud(dt);
}

