128: function ensureAudio(){if(!audioCtx){const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return null;audioCtx=new AudioContext();masterGain=audioCtx.createGain();masterGain.gain.value=muted?0:Number($('#volume-slider')?.value??70)/100;masterGain.connect(audioCtx.destination);ambienceFilter=audioCtx.createBiquadFilter();ambienceFilter.type='lowpass';ambienceFilter.frequency.value=150;ambienceGain=audioCtx.createGain();ambienceGain.gain.value=0;ambienceFilter.connect(ambienceGain);ambienceGain.connect(masterGain);for(const [freq,level,type] of [[46,.026,'sine'],[51,.014,'triangle']]){const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.value=level;osc.connect(gain);gain.connect(ambienceFilter);osc.start();}audioCtx.addEventListener('statechange',()=>{if(audioCtx?.state==='suspended'&&!document.hidden)audioCtx.resume().catch(()=>{});});}if(audioCtx.state==='suspended')audioCtx.resume().catch(()=>{});return audioCtx;}
129: function setAudioScene(active,threat=audioThreat){audioSceneActive=active;audioThreat=clamp(threat,0,1);const ctx=ensureAudio();if(!ctx||!ambienceGain)return;const now=ctx.currentTime;ambienceGain.gain.cancelScheduledValues(now);ambienceGain.gain.setTargetAtTime(active?.82+audioThreat*.32:0,now,.8);ambienceFilter.frequency.setTargetAtTime(150+audioThreat*380,now,1.2);}
130: function setMasterVolume(){const ctx=ensureAudio();if(!ctx||!masterGain)return;masterGain.gain.setTargetAtTime(muted?0:Number($('#volume-slider')?.value??70)/100,ctx.currentTime,.04);}
131: function playTone(freq=220,duration=.2,type='sine',volume=.1){if(muted)return;try{const ctx=ensureAudio();if(!ctx)return;const osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(volume,now);gain.gain.exponentialRampToValueAtTime(.001,now+Math.max(.025,duration));osc.connect(gain);gain.connect(masterGain);osc.start(now);osc.stop(now+duration+.01);}catch(e){}}
