import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
const runtime='/home/runner/.local/share/omgithub-playwright'
const require=createRequire(`${runtime}/package.json`)
const {chromium}=require('playwright')
const config=await import(`${runtime}/linux.json`,{with:{type:'json'}}).catch(()=>null)
const browser=await chromium.launch({...(config?.default?.browser?.launchOptions||JSON.parse((await import('node:fs')).readFileSync(`${runtime}/linux.json`,'utf8')).browser.launchOptions)})
const page=await browser.newPage({viewport:{width:1280,height:720}})
const defects=[]
page.on('pageerror',e=>defects.push(e.message))
page.on('console',m=>{if(m.type()==='error')defects.push(m.text())})
await page.goto('http://127.0.0.1:3000',{waitUntil:'load'})
await page.locator('[data-lang="en"]').click()
await page.locator('[data-action="intro"]').click()
await page.locator('#skip-intro').click()
await page.waitForTimeout(500)
const hud=()=>page.locator('#objective-text').innerText()
const progress=()=>page.locator('#objective-progress').innerText()
async function key(k,ms){await page.keyboard.down(k);await page.waitForTimeout(ms);await page.keyboard.up(k);await page.waitForTimeout(150)}
async function go(k,ms){await page.keyboard.down('Shift');await key(k,ms);await page.keyboard.up('Shift');await page.waitForTimeout(150)}
async function act(label){await page.keyboard.press('e');await page.waitForTimeout(400);console.log(label,JSON.stringify(await hud()),JSON.stringify(await progress()),'toast=',JSON.stringify((await page.locator('#toast').innerText().catch(()=>''))))}
try {
 console.log('Start',await hud())
 await act('journal')
 await go('w',1400); await act('security')
 await go('w',2400); await go('a',780); await act('MED card')
 await go('d',780); await go('w',1100); await act('MED access')
 await go('w',3100); await go('d',780); await act('LAB card')
 await go('a',780); await go('w',1200); await act('LAB access')
 await go('w',1100); await go('a',580); await act('REACTOR card')
 await go('d',1350); await go('w',1300); await act('generator')
 await go('w',3400); await go('a',120); await act('elevator call')
 console.log('Called. Kiting for 60 sec...')
 // Sprint back and forth through the connected corridor while the elevator arrives.
 for(let i=0;i<4;i++){await go('w',6500);await go('s',6500);console.log(`kite ${i+1}`,JSON.stringify(await hud()),await page.locator('#health-value').innerText().catch(()=>'?'))}
 await go('w',3000); await go('s',4000); await act('board elevator')
 console.log('Ending visible',await page.locator('#ending-title').innerText().catch(()=>'(no ending)'))
 mkdirSync('/tmp/opencode',{recursive:true})
 await page.screenshot({path:'/tmp/opencode/facility-latest.jpg',type:'jpeg',quality:82})
 console.log('Screenshot /tmp/opencode/facility-latest.jpg 1280x720')
 console.log('Errors',defects)
} finally {await browser.close()}

