import { createRequire } from 'node:module'
import { mkdirSync } from 'node:fs'
const runtime='/home/runner/.local/share/omgithub-playwright'
const require=createRequire(`${runtime}/package.json`)
const {chromium}=require('playwright')
const config=JSON.parse((await import('node:fs')).readFileSync(`${runtime}/linux.json`,'utf8'))
const browser=await chromium.launch({...config.browser.launchOptions,headless:true})
const page=await browser.newPage({viewport:{width:1280,height:720}})
const defects=[]
page.on('pageerror',e=>defects.push(e.message))
page.on('console',m=>{if(m.type()==='error')defects.push(m.text())})
try {
 await page.goto('http://127.0.0.1:3000/?playtest',{waitUntil:'load'})
 await page.locator('[data-lang="en"]').evaluate(el=>el.click())
 await page.evaluate(()=>window.__f.beginGame())
 await page.waitForTimeout(500)
 const result=await page.evaluate(async()=>{
  const f=window.__f,{game,player}=f
  const perform=(label)=>{const it=f.interactables.find(x=>x.label.includes(label));if(!it)throw new Error(`Missing interaction: ${label}`);player.pos.copy(it.pos);it.fn();return it.label}
  const hud=()=>document.querySelector('#objective-text').textContent
  const steps=[]
  const check=(name,expected)=>{steps.push({name,hud:hud(),keys:game.keys,objectives:[...game.objectiveDone]});if(expected&&!hud().toLowerCase().includes(expected.toLowerCase()))throw new Error(`${name}: unexpected HUD ${hud()}`)}
  check('start','Read the journal')
  perform('Read bloodstained journal');check('story journal','Unlock the security door')
  perform('Unlock security door');check('security door','MED keycard')
  perform('Take MED keycard');check('MED keycard','Scan the MED card')
  perform('Scan MED card');check('MED access','LAB keycard')
  perform('Take LAB keycard');check('LAB keycard','Scan the LAB card')
  perform('Scan LAB card');check('LAB access','REACTOR keycard')
  perform('Take REACTOR keycard');check('REACTOR keycard','Restore main power')
  perform('Restore main generator');check('generator','Call the surface elevator')
  perform('Call surface elevator');
  const monster=f.getMonster();const before=game.enemyDist
  for(let i=0;i<50;i++)f.update(.1)
  const threat={active:monster.userData.active,initialDistance:before,distanceAfter5s:game.enemyDist,healthAfter5s:game.health}
  monster.userData.active=false
  for(let i=0;i<600;i++)f.update(.1)
  check('elevator wait','Board the elevator')
  perform('Call surface elevator');
  await new Promise(resolve=>requestAnimationFrame(()=>resolve()))
  return {steps,threat,ending:document.querySelector('#ending-title').textContent,mode:game.mode,health:game.health}
 })
 console.log('Progression result',JSON.stringify(result,null,2))
 mkdirSync('/tmp/opencode',{recursive:true})
 await page.screenshot({path:'/tmp/opencode/facility-latest.jpg',type:'jpeg',quality:82})
 console.log('Screenshot /tmp/opencode/facility-latest.jpg 1280x720 JPEG')
 console.log('Errors',JSON.stringify(defects))
} finally {await browser.close()}

